/*
 * AnigmaQR — a small, local, dependency-free QR Code (ISO/IEC 18004) encoder.
 * Written for this project so no code or fonts are fetched from a CDN. Supports byte-mode
 * encoding only (which is all this app needs), versions 1-40, error correction level L or M.
 * This is a from-scratch implementation of the public algorithm (Reed-Solomon over GF(256),
 * BCH format/version info, standard mask-penalty rules) — it has not been checked against
 * an independent test suite of real-world scanners, so treat it as best-effort: if a
 * generated code does not scan, use the app's "copy result" fallback instead.
 */
(function (global) {
  'use strict';

  // ---------------------------------------------------------------- GF(256) arithmetic
  const GF_EXP = new Array(512);
  const GF_LOG = new Array(256);
  (function initGF() {
    let x = 1;
    for (let i = 0; i < 255; i++) {
      GF_EXP[i] = x;
      GF_LOG[x] = i;
      x <<= 1;
      if (x & 0x100) x ^= 0x11D;
    }
    for (let i = 255; i < 512; i++) GF_EXP[i] = GF_EXP[i - 255];
  })();
  function gfMul(a, b) {
    if (a === 0 || b === 0) return 0;
    return GF_EXP[GF_LOG[a] + GF_LOG[b]];
  }

  function rsGeneratorPoly(degree) {
    let poly = [1];
    for (let i = 0; i < degree; i++) {
      const next = new Array(poly.length + 1).fill(0);
      for (let j = 0; j < poly.length; j++) {
        next[j] ^= gfMul(poly[j], GF_EXP[i]);
        next[j + 1] ^= poly[j];
      }
      poly = next;
    }
    return poly; // highest-degree coefficient first
  }

  function rsEncode(dataCodewords, ecCount) {
    const gen = rsGeneratorPoly(ecCount);
    const res = dataCodewords.concat(new Array(ecCount).fill(0));
    for (let i = 0; i < dataCodewords.length; i++) {
      const coef = res[i];
      if (coef === 0) continue;
      for (let j = 0; j < gen.length; j++) {
        res[i + j] ^= gfMul(gen[j], coef);
      }
    }
    return res.slice(dataCodewords.length);
  }

  // ---------------------------------------------------------------- capacity / block tables
  // [totalCodewords, ecCodewordsPerBlock, blocksGroup1, dataPerBlockGroup1, blocksGroup2, dataPerBlockGroup2]
  // Level L and M, versions 1-40 (ISO/IEC 18004 Table 9 / Annex). This table is widely
  // reproduced across open-source QR encoders.
  const RS_BLOCKS = {
    L: [
      [26, 7, 1, 19, 0, 0], [44, 10, 1, 34, 0, 0], [70, 15, 1, 55, 0, 0], [100, 20, 1, 80, 0, 0],
      [134, 26, 1, 108, 0, 0], [172, 18, 2, 68, 0, 0], [196, 20, 2, 78, 0, 0], [242, 24, 2, 97, 0, 0],
      [292, 30, 2, 116, 0, 0], [346, 18, 2, 68, 2, 69], [404, 20, 4, 81, 0, 0], [466, 24, 2, 92, 2, 93],
      [532, 26, 4, 107, 0, 0], [581, 30, 3, 115, 1, 116], [655, 22, 5, 87, 1, 88], [733, 24, 5, 98, 1, 99],
      [815, 28, 1, 107, 5, 108], [901, 30, 5, 120, 1, 121], [991, 28, 3, 113, 4, 114], [1085, 28, 3, 107, 5, 108],
      [1156, 28, 4, 116, 4, 117], [1258, 28, 2, 111, 7, 112], [1364, 30, 4, 121, 5, 122], [1474, 30, 6, 117, 4, 118],
      [1588, 26, 8, 106, 4, 107], [1706, 28, 10, 114, 2, 115], [1828, 30, 8, 122, 4, 123], [1921, 30, 3, 117, 10, 118],
      [2051, 30, 7, 116, 7, 117], [2185, 30, 5, 115, 10, 116], [2323, 30, 13, 115, 3, 116], [2465, 30, 17, 115, 0, 0],
      [2611, 30, 17, 115, 1, 116], [2761, 30, 13, 115, 6, 116], [2876, 30, 12, 121, 7, 122], [3034, 30, 6, 121, 14, 122],
      [3196, 30, 17, 122, 4, 123], [3362, 30, 4, 122, 18, 123], [3532, 30, 20, 117, 4, 118], [3706, 30, 19, 118, 6, 119]
    ],
    M: [
      [26, 10, 1, 16, 0, 0], [44, 16, 1, 28, 0, 0], [70, 26, 1, 44, 0, 0], [100, 18, 2, 32, 0, 0],
      [134, 24, 2, 43, 0, 0], [172, 16, 4, 27, 0, 0], [196, 18, 4, 31, 0, 0], [242, 22, 2, 38, 2, 39],
      [292, 22, 3, 36, 2, 37], [346, 26, 4, 43, 1, 44], [404, 30, 1, 50, 4, 51], [466, 22, 6, 36, 2, 37],
      [532, 22, 8, 37, 1, 38], [581, 24, 4, 40, 5, 41], [655, 24, 5, 41, 5, 42], [733, 28, 7, 45, 3, 46],
      [815, 28, 10, 46, 1, 47], [901, 26, 9, 43, 4, 44], [991, 26, 3, 44, 11, 45], [1085, 26, 3, 41, 13, 42],
      [1156, 26, 17, 42, 0, 0], [1258, 28, 17, 46, 0, 0], [1364, 28, 4, 47, 14, 48], [1474, 28, 6, 45, 14, 46],
      [1588, 28, 8, 47, 13, 48], [1706, 28, 19, 46, 4, 47], [1828, 28, 22, 45, 3, 46], [1921, 28, 3, 45, 23, 46],
      [2051, 28, 21, 45, 7, 46], [2185, 28, 19, 47, 10, 48], [2323, 28, 2, 46, 29, 47], [2465, 28, 10, 46, 23, 47],
      [2611, 28, 14, 46, 21, 47], [2761, 28, 14, 46, 23, 47], [2876, 28, 12, 47, 26, 48], [3034, 28, 6, 47, 34, 48],
      [3196, 28, 29, 46, 14, 47], [3362, 28, 13, 46, 32, 47], [3532, 28, 40, 47, 7, 48], [3706, 28, 18, 47, 31, 48]
    ]
  };

  // Byte-mode capacity in bytes for each version, at L and M (character-count indicator +
  // mode overhead already accounted for). Used to pick the smallest version that fits.
  function dataCapacityBytes(version, level) {
    const row = RS_BLOCKS[level][version - 1];
    const totalData = row[2] * row[3] + row[4] * row[5];
    return totalData;
  }

  // Alignment pattern center coordinates per version (empty for version 1).
  const ALIGNMENT_COORDS = {
    2: [6, 18], 3: [6, 22], 4: [6, 26], 5: [6, 30], 6: [6, 34], 7: [6, 22, 38], 8: [6, 24, 42],
    9: [6, 26, 46], 10: [6, 28, 50], 11: [6, 30, 54], 12: [6, 32, 58], 13: [6, 34, 62],
    14: [6, 26, 46, 66], 15: [6, 26, 48, 70], 16: [6, 26, 50, 74], 17: [6, 30, 54, 78],
    18: [6, 30, 56, 82], 19: [6, 30, 58, 86], 20: [6, 34, 62, 90], 21: [6, 28, 50, 72, 94],
    22: [6, 26, 50, 74, 98], 23: [6, 30, 54, 78, 102], 24: [6, 28, 54, 80, 106], 25: [6, 32, 58, 84, 110],
    26: [6, 30, 58, 86, 114], 27: [6, 34, 62, 90, 118], 28: [6, 26, 50, 74, 98, 122], 29: [6, 30, 54, 78, 102, 126],
    30: [6, 26, 52, 78, 104, 130], 31: [6, 30, 56, 82, 108, 134], 32: [6, 34, 60, 86, 112, 138],
    33: [6, 30, 58, 86, 114, 142], 34: [6, 34, 62, 90, 118, 146], 35: [6, 30, 54, 78, 102, 126, 150],
    36: [6, 24, 50, 76, 102, 128, 154], 37: [6, 28, 54, 80, 106, 132, 158], 38: [6, 32, 58, 84, 110, 136, 162],
    39: [6, 26, 54, 82, 110, 138, 166], 40: [6, 30, 58, 86, 114, 142, 170]
  };

  // ---------------------------------------------------------------- bit buffer
  function BitBuffer() {
    this.bytes = [];
    this.bitLength = 0;
  }
  BitBuffer.prototype.put = function (val, len) {
    for (let i = len - 1; i >= 0; i--) this.putBit((val >>> i) & 1);
  };
  BitBuffer.prototype.putBit = function (bit) {
    const idx = Math.floor(this.bitLength / 8);
    if (this.bytes.length <= idx) this.bytes.push(0);
    if (bit) this.bytes[idx] |= (0x80 >>> (this.bitLength % 8));
    this.bitLength++;
  };

  // ---------------------------------------------------------------- data encoding (byte mode)
  function encodeDataBits(bytes, version, level) {
    const buf = new BitBuffer();
    buf.put(0b0100, 4); // byte-mode indicator
    const countBits = version <= 9 ? 8 : 16;
    buf.put(bytes.length, countBits);
    for (let i = 0; i < bytes.length; i++) buf.put(bytes[i], 8);

    const capacityBits = dataCapacityBytes(version, level) * 8;
    // terminator (up to 4 bits)
    const term = Math.min(4, capacityBits - buf.bitLength);
    if (term > 0) buf.put(0, term);
    // pad to byte boundary
    while (buf.bitLength % 8 !== 0) buf.putBit(0);
    // pad bytes 0xEC / 0x11 alternating
    const padBytes = [0xEC, 0x11];
    let pi = 0;
    while (buf.bitLength < capacityBits) { buf.put(padBytes[pi % 2], 8); pi++; }
    return buf.bytes;
  }

  function buildCodewords(dataBytes, version, level) {
    const row = RS_BLOCKS[level][version - 1];
    const ecCount = row[1];
    const blocks = [];
    let offset = 0;
    for (let i = 0; i < row[2]; i++) { blocks.push(dataBytes.slice(offset, offset + row[3])); offset += row[3]; }
    for (let i = 0; i < row[4]; i++) { blocks.push(dataBytes.slice(offset, offset + row[5])); offset += row[5]; }
    const ecBlocks = blocks.map(function (b) { return rsEncode(b, ecCount); });

    const maxDataLen = Math.max.apply(null, blocks.map(function (b) { return b.length; }));
    const interleaved = [];
    for (let i = 0; i < maxDataLen; i++) {
      for (const b of blocks) if (i < b.length) interleaved.push(b[i]);
    }
    const maxEcLen = ecCount;
    for (let i = 0; i < maxEcLen; i++) {
      for (const eb of ecBlocks) interleaved.push(eb[i]);
    }
    return interleaved;
  }

  // ---------------------------------------------------------------- matrix construction
  function Matrix(size) {
    this.size = size;
    this.modules = [];
    this.reserved = [];
    for (let i = 0; i < size; i++) { this.modules.push(new Array(size).fill(false)); this.reserved.push(new Array(size).fill(false)); }
  }
  Matrix.prototype.set = function (r, c, val, isFunction) {
    if (r < 0 || r >= this.size || c < 0 || c >= this.size) return;
    this.modules[r][c] = val;
    if (isFunction) this.reserved[r][c] = true;
  };
  Matrix.prototype.get = function (r, c) { return this.modules[r][c]; };
  Matrix.prototype.isReserved = function (r, c) { return this.reserved[r][c]; };

  function placeFinder(m, r, c) {
    for (let dr = -1; dr <= 7; dr++) {
      for (let dc = -1; dc <= 7; dc++) {
        const rr = r + dr, cc = c + dc;
        if (rr < 0 || rr >= m.size || cc < 0 || cc >= m.size) continue;
        const isBorder = dr === -1 || dr === 7 || dc === -1 || dc === 7;
        const isRing = (dr >= 0 && dr <= 6 && (dc === 0 || dc === 6)) || (dc >= 0 && dc <= 6 && (dr === 0 || dr === 6));
        const isCore = dr >= 2 && dr <= 4 && dc >= 2 && dc <= 4;
        m.set(rr, cc, !isBorder && (isRing || isCore), true);
      }
    }
  }

  function placeFunctionPatterns(m, version) {
    placeFinder(m, 0, 0);
    placeFinder(m, 0, m.size - 7);
    placeFinder(m, m.size - 7, 0);

    // timing patterns
    for (let i = 8; i < m.size - 8; i++) {
      m.set(6, i, i % 2 === 0, true);
      m.set(i, 6, i % 2 === 0, true);
    }

    // alignment patterns
    const coords = ALIGNMENT_COORDS[version] || [];
    for (const r of coords) {
      for (const c of coords) {
        // skip positions overlapping the finder patterns
        if ((r <= 8 && c <= 8) || (r <= 8 && c >= m.size - 9) || (r >= m.size - 9 && c <= 8)) continue;
        for (let dr = -2; dr <= 2; dr++) {
          for (let dc = -2; dc <= 2; dc++) {
            const ring = Math.max(Math.abs(dr), Math.abs(dc));
            m.set(r + dr, c + dc, ring !== 1, true);
          }
        }
      }
    }

    // dark module
    m.set(m.size - 8, 8, true, true);

    // reserve format info areas
    for (let i = 0; i < 9; i++) { m.reserved[8][i] = true; m.reserved[i][8] = true; }
    for (let i = 0; i < 8; i++) { m.reserved[8][m.size - 1 - i] = true; m.reserved[m.size - 1 - i][8] = true; }

    // reserve version info areas (version 7+)
    if (version >= 7) {
      for (let r = 0; r < 6; r++) for (let c = 0; c < 3; c++) { m.reserved[r][m.size - 11 + c] = true; m.reserved[m.size - 11 + c][r] = true; }
    }
  }

  function placeData(m, codewordBytes, version) {
    const bits = [];
    for (const byte of codewordBytes) for (let i = 7; i >= 0; i--) bits.push((byte >>> i) & 1);
    let bitIndex = 0;
    let dir = -1; // upward
    let col = m.size - 1;
    while (col > 0) {
      if (col === 6) col--; // skip vertical timing column
      for (let i = 0; i < m.size; i++) {
        const row = dir === -1 ? m.size - 1 - i : i;
        for (let dc = 0; dc < 2; dc++) {
          const c = col - dc;
          if (m.isReserved(row, c)) continue;
          const bit = bitIndex < bits.length ? bits[bitIndex] : 0;
          bitIndex++;
          m.set(row, c, !!bit, false);
        }
      }
      col -= 2;
      dir = -dir;
    }
  }

  function applyMask(m, maskId, isFunctionAt) {
    for (let r = 0; r < m.size; r++) {
      for (let c = 0; c < m.size; c++) {
        if (isFunctionAt(r, c)) continue;
        let flip = false;
        switch (maskId) {
          case 0: flip = (r + c) % 2 === 0; break;
          case 1: flip = r % 2 === 0; break;
          case 2: flip = c % 3 === 0; break;
          case 3: flip = (r + c) % 3 === 0; break;
          case 4: flip = (Math.floor(r / 2) + Math.floor(c / 3)) % 2 === 0; break;
          case 5: flip = ((r * c) % 2) + ((r * c) % 3) === 0; break;
          case 6: flip = (((r * c) % 2) + ((r * c) % 3)) % 2 === 0; break;
          case 7: flip = (((r + c) % 2) + ((r * c) % 3)) % 2 === 0; break;
        }
        if (flip) m.modules[r][c] = !m.modules[r][c];
      }
    }
  }

  function maskPenalty(m) {
    const size = m.size;
    let penalty = 0;
    // N1: runs of 5+ same-colour modules, per row and column
    function runsPenalty(getVal) {
      let p = 0;
      for (let i = 0; i < size; i++) {
        let runColor = null, runLen = 0;
        for (let j = 0; j < size; j++) {
          const v = getVal(i, j);
          if (v === runColor) { runLen++; } else { if (runLen >= 5) p += runLen - 2; runColor = v; runLen = 1; }
        }
        if (runLen >= 5) p += runLen - 2;
      }
      return p;
    }
    penalty += runsPenalty(function (r, c) { return m.modules[r][c]; });
    penalty += runsPenalty(function (r, c) { return m.modules[c][r]; });

    // N2: 2x2 blocks of same colour
    for (let r = 0; r < size - 1; r++) {
      for (let c = 0; c < size - 1; c++) {
        const v = m.modules[r][c];
        if (v === m.modules[r][c + 1] && v === m.modules[r + 1][c] && v === m.modules[r + 1][c + 1]) penalty += 3;
      }
    }

    // N3: finder-like patterns 1:1:3:1:1
    const patternA = [true, false, true, true, true, false, true, false, false, false, false];
    const patternB = [false, false, false, false, true, false, true, true, true, false, true];
    function matchesAt(arr, idx, pat) {
      for (let k = 0; k < pat.length; k++) if (arr[idx + k] !== pat[k]) return false;
      return true;
    }
    function scanLine(arr) {
      let p = 0;
      for (let i = 0; i <= arr.length - 11; i++) {
        if (matchesAt(arr, i, patternA) || matchesAt(arr, i, patternB)) p += 40;
      }
      return p;
    }
    for (let r = 0; r < size; r++) penalty += scanLine(m.modules[r]);
    for (let c = 0; c < size; c++) { const col = []; for (let r = 0; r < size; r++) col.push(m.modules[r][c]); penalty += scanLine(col); }

    // N4: overall dark proportion
    let dark = 0;
    for (let r = 0; r < size; r++) for (let c = 0; c < size; c++) if (m.modules[r][c]) dark++;
    const percent = (dark * 100) / (size * size);
    const prevMultiple = Math.floor(percent / 5) * 5;
    const nextMultiple = prevMultiple + 5;
    penalty += Math.min(Math.abs(prevMultiple - 50) / 5, Math.abs(nextMultiple - 50) / 5) * 10;

    return penalty;
  }

  function bchFormat(data) {
    // BCH(15,5) for format info, generator 0x537, final XOR mask 0x5412.
    let d = data << 10;
    const g = 0x537;
    for (let i = 4; i >= 0; i--) {
      if (d & (1 << (i + 10))) d ^= g << i;
    }
    return ((data << 10) | d) ^ 0x5412;
  }
  function bchVersion(data) {
    let d = data << 12;
    const g = 0x1F25;
    for (let i = 5; i >= 0; i--) {
      if (d & (1 << (i + 12))) d ^= g << i;
    }
    return (data << 12) | d;
  }

  function placeFormatInfo(m, level, maskId) {
    const levelBits = { L: 1, M: 0, Q: 3, H: 2 }[level]; // ISO indicator bits for EC level
    const bits15 = bchFormat((levelBits << 3) | maskId);
    const size = m.size;
    for (let i = 0; i <= 5; i++) m.set(8, i, !!((bits15 >> i) & 1), true);
    m.set(8, 7, !!((bits15 >> 6) & 1), true);
    m.set(8, 8, !!((bits15 >> 7) & 1), true);
    m.set(7, 8, !!((bits15 >> 8) & 1), true);
    for (let i = 9; i <= 14; i++) m.set(14 - i, 8, !!((bits15 >> i) & 1), true);

    for (let i = 0; i <= 7; i++) m.set(size - 1 - i, 8, !!((bits15 >> i) & 1), true);
    for (let i = 8; i <= 14; i++) m.set(8, size - 15 + i, !!((bits15 >> i) & 1), true);
  }

  function placeVersionInfo(m, version) {
    if (version < 7) return;
    const bits18 = bchVersion(version);
    const size = m.size;
    for (let i = 0; i < 18; i++) {
      const bit = !!((bits18 >> i) & 1);
      const row = i % 3, col = Math.floor(i / 3);
      m.set(row, size - 11 + col, bit, true);
      m.set(size - 11 + col, row, bit, true);
    }
  }

  // ---------------------------------------------------------------- top-level encode
  function pickVersion(byteLength, level) {
    for (let v = 1; v <= 40; v++) {
      const cap = dataCapacityBytes(v, level);
      const overheadBits = (v <= 9 ? 4 + 8 : 4 + 16);
      const usableBytes = Math.floor((cap * 8 - overheadBits) / 8);
      if (byteLength <= usableBytes) return v;
    }
    return null;
  }

  function maxBytesForLevel(level) {
    return dataCapacityBytes(40, level) - 3; // rough ceiling minus mode/count overhead
  }

  function encode(text, level) {
    level = level || 'L';
    const bytes = Array.from(new TextEncoder().encode(text));
    const version = pickVersion(bytes.length, level);
    if (!version) { const e = new Error('too-long'); e.code = 'too-long'; throw e; }

    const dataBytes = encodeDataBits(bytes, version, level);
    const codewords = buildCodewords(dataBytes, version, level);

    const size = 21 + (version - 1) * 4;
    const m = new Matrix(size);
    placeFunctionPatterns(m, version);
    placeData(m, codewords, version);

    function isFunctionAt(r, c) { return m.isReserved(r, c); }
    let bestMask = 0, bestPenalty = Infinity, bestModules = null;
    for (let mask = 0; mask < 8; mask++) {
      const trial = new Matrix(size);
      trial.modules = m.modules.map(function (row) { return row.slice(); });
      trial.reserved = m.reserved;
      applyMask(trial, mask, isFunctionAt);
      const p = maskPenalty(trial);
      if (p < bestPenalty) { bestPenalty = p; bestMask = mask; bestModules = trial.modules; }
    }
    m.modules = bestModules;
    placeFormatInfo(m, level, bestMask);
    placeVersionInfo(m, version);

    return { size: size, modules: m.modules, version: version };
  }

  function renderToCanvas(container, text, opts) {
    opts = opts || {};
    const level = opts.correctLevel || 'L';
    const targetPx = opts.width || 200;
    const result = encode(text, level);
    const quiet = 4;
    const totalModules = result.size + quiet * 2;
    const scale = Math.max(1, Math.floor(targetPx / totalModules));
    const px = totalModules * scale;

    const canvas = document.createElement('canvas');
    canvas.width = px; canvas.height = px;
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, px, px);
    ctx.fillStyle = '#000000';
    for (let r = 0; r < result.size; r++) {
      for (let c = 0; c < result.size; c++) {
        if (result.modules[r][c]) {
          ctx.fillRect((c + quiet) * scale, (r + quiet) * scale, scale, scale);
        }
      }
    }
    container.innerHTML = '';
    container.appendChild(canvas);
    return canvas;
  }

  global.AnigmaQR = {
    encode: encode,
    render: renderToCanvas,
    maxBytesForLevel: maxBytesForLevel,
    pickVersion: pickVersion
  };
})(typeof window !== 'undefined' ? window : this);
